mapper.insert:
INSERT INTO `report` (
    reporter_id, target_type, target_id, reason, status, create_time, update_time
) VALUES (
    #{reporterId}, #{targetType}, #{targetId}, #{reason}, #{status}, NOW(), NOW()
)

mapper.select:
SELECT *
FROM `report`
WHERE reporter_id = #{reporterId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 0
ORDER BY id DESC
LIMIT 1
